import {runForecastExperiment,forecastSynthetic} from './forecast-core.mjs';
const $=id=>document.getElementById(id),pct=v=>v===null?'Not defined':`${(v*100).toFixed(1)}%`,num=v=>v===null?'Not defined':v.toFixed(3);let experiment=null;
$('train-forecast').addEventListener('click',()=>{try{
  experiment=runForecastExperiment();const m=experiment.metrics,b=experiment.baselineMetrics;
  $('forecast-results').innerHTML=`<div class="forecast-metrics">${[['Scored / total',`${m.scored} / ${m.total}`],['Abstained',m.abstained],['False alarms',m.falseAlarms],['Missed incidents',m.missedIncidents],['Precision',pct(m.precision)],['Recall on scored rows',pct(m.recall)]].map(([title,value])=>`<div><span>${title}</span><strong>${value}</strong></div>`).join('')}</div><section class="panel"><div class="panel-heading"><h2>Later-outcome evaluation</h2><span class="chip">AUTHORED DATA</span></div><div class="scenario-context-body"><p>Training outcomes known through ${experiment.model.trainedThrough}; first later test issuance ${experiment.firstTestIssuedAt}. ${experiment.purgedCount} record excluded as a gap. ${m.abstained} abstentions (${m.abstainedIncidents} with a later positive authored outcome) stay unresolved and are excluded from the scored precision/recall and probability errors.</p><div class="forecast-comparison"><div><span>Learned logistic model</span><strong>Brier ${num(m.brier)}</strong><p>Log loss ${num(m.logLoss)}</p></div><div><span>Training base-rate baseline</span><strong>Brier ${num(b.brier)}</strong><p>Log loss ${num(b.logLoss)} · Same scored rows</p></div></div><p>Lower probability errors are better on this fictional test. They do not establish performance on real attacks. Threshold and training settings were fixed before test outcomes were scored; the visible fixture is not blinded.</p><h3>Reliability bins</h3><div class="reliability-bins">${m.bins.map(bin=>`<article><span>${pct(bin.from)}–${pct(bin.to)}</span><strong>${bin.count} rows</strong><p>Mean forecast ${pct(bin.meanForecast)}<br>Observed fictional rate ${pct(bin.observedRate)}</p></article>`).join('')}</div><details><summary>Inspect held-out forecasts</summary>${experiment.forecasts.slice(0,12).map(r=>`<p>${r.issuedAt} / ${r.region} · ${r.probability===null?'Abstained':pct(r.probability)} · Authored later outcome ${r.outcome} (${r.outcomeKnownAt})</p>`).join('')}<p>Showing the first 12 of ${experiment.forecasts.length} later records.</p></details></div></section>`;
  $('forecast-estimate').disabled=false;$('forecast-error').textContent='';$('train-forecast').textContent='Run fixed experiment again';
}catch(e){$('forecast-error').textContent=e.message;}});
$('forecast-input').addEventListener('submit',event=>{event.preventDefault();try{if(!experiment)throw new Error('Train the synthetic baseline first.');const issuedAt=new Date(Date.parse(experiment.model.trainedThrough+'T00:00:00Z')+86400000*14).toISOString().slice(0,10);const result=forecastSynthetic(experiment.model,{synthetic:true,region:'training-region-IN-1',issuedAt,featuresAsOf:issuedAt,features:{warningGroups:Number($('forecast-warnings').value),reposts:Number($('forecast-reposts').value),contradictingGroups:Number($('forecast-contradictions').value),coverage:Number($('forecast-coverage').value)}});$('forecast-estimate-result').textContent=result.status==='abstained'?`Abstained: ${result.reason}`:`Synthetic seven-day outcome estimate: ${pct(result.probability)}. This is a toy-model output, not a real attack probability. Feature contributions are statistical associations in authored data, not causes or evidence of intent.`;}catch(e){$('forecast-estimate-result').textContent=e.message;}});
